def comps(grid, vals):
    R=len(grid); C=len(grid[0]); seen=set(); out=[]
    for a in range(R):
        for b in range(C):
            if grid[a][b] in vals and (a,b) not in seen:
                q=[(a,b)]; seen.add((a,b)); comp=[]
                while q:
                    x,y=q.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<R and 0<=ny<C and grid[nx][ny] in vals and (nx,ny) not in seen:
                            seen.add((nx,ny)); q.append((nx,ny))
                out.append(comp)
    return out
