def T8(g,t):
    if t==0: return g
    if t==1: return [list(r) for r in zip(*g)]            # dmirror
    if t==2: return [r[::-1] for r in g]                  # hmirror
    if t==3: return g[::-1]                               # vmirror
    if t==4: return [list(r) for r in zip(*g)][::-1]      # rot90
    if t==5: return [r[::-1] for r in g][::-1]            # rot180
    if t==6: return [list(r) for r in zip(*g[::-1])]      # rot270
    if t==7: return [r[::-1] for r in zip(*g)]            # anti
